import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import session from 'express-session';

const app = express();

// Session configuration
app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

app.use(express.json());

// Circuit breaker state
interface CircuitState {
  failures: number;
  lastFailure: number;
  state: 'closed' | 'open' | 'half-open';
}

const circuitBreaker: CircuitState = {
  failures: 0,
  lastFailure: 0,
  state: 'closed'
};

const FAILURE_THRESHOLD = 5;
const RECOVERY_TIMEOUT = 30000;

// CSRF secret: generated at runtime (or loaded from secure config/env), never hardcoded
const CSRF_SECRET = process.env.CSRF_SECRET || crypto.randomBytes(32).toString('hex');

// CSRF token generation and validation
function generateCsrfToken(sessionId: string): string {
  const hmac = crypto.createHmac('sha256', CSRF_SECRET);
  hmac.update(sessionId);
  return hmac.digest('hex');
}

function validateCsrfToken(req: Request): boolean {
  const token = req.headers['x-csrf-token'] as string;
  const sessionId = req.sessionID;
  if (!token || !sessionId) return false;
  const expected = generateCsrfToken(sessionId);
  const tokenBuf = Buffer.from(token, 'hex');
  const expectedBuf = Buffer.from(expected, 'hex');
  // Guard against timingSafeEqual throwing on length mismatch
  if (tokenBuf.length !== expectedBuf.length) return false;
  return crypto.timingSafeEqual(tokenBuf, expectedBuf);
}

// Origin validation middleware
function validateOrigin(req: Request, res: Response, next: NextFunction): void {
  const origin = req.headers['origin'];
  const referer = req.headers['referer'];
  const allowedOrigins = ['https://ml-dashboard.internal.corp'];

  // Skip validation for safe methods
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    next();
    return;
  }

  // Origin validation applies regardless of circuit breaker state
  // Circuit state should never weaken security controls
  if (origin && !allowedOrigins.includes(origin)) {
    res.status(403).json({ error: 'Invalid origin' });
    return;
  }

  if (!origin && referer) {
    const refererUrl = new URL(referer);
    if (!allowedOrigins.includes(refererUrl.origin)) {
      res.status(403).json({ error: 'Invalid referer' });
      return;
    }
  }

  if (!origin && !referer) {
    res.status(403).json({ error: 'Missing origin header' });
    return;
  }

  next();
}

// CSRF middleware
function csrfProtection(req: Request, res: Response, next: NextFunction): void {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    next();
    return;
  }

  // All state-changing requests require CSRF validation, no exceptions
  if (!validateCsrfToken(req)) {
    res.status(403).json({ error: 'Invalid CSRF token' });
    return;
  }

  next();
}

app.use(validateOrigin);
app.use(csrfProtection);

// ML inference endpoint
app.post('/api/inference', async (req: Request, res: Response) => {
  if (circuitBreaker.state === 'open') {
    const elapsed = Date.now() - circuitBreaker.lastFailure;
    if (elapsed > RECOVERY_TIMEOUT) {
      circuitBreaker.state = 'half-open';
    } else {
      res.status(503).json({ error: 'Service unavailable - circuit open' });
      return;
    }
  }

  try {
    const { model, input, parameters } = req.body;
    // Simulate ML inference
    const result = { prediction: Math.random(), model, timestamp: Date.now() };

    if (circuitBreaker.state === 'half-open') {
      circuitBreaker.state = 'closed';
      circuitBreaker.failures = 0;
    }

    res.json(result);
  } catch (error) {
    circuitBreaker.failures++;
    circuitBreaker.lastFailure = Date.now();
    if (circuitBreaker.failures >= FAILURE_THRESHOLD) {
      circuitBreaker.state = 'open';
    }
    res.status(500).json({ error: 'Inference failed' });
  }
});

// Circuit breaker management (requires full auth)
app.post('/api/circuit/trip', (req: Request, res: Response) => {
  circuitBreaker.state = 'open';
  circuitBreaker.lastFailure = Date.now();
  res.json({ status: 'Circuit tripped' });
});

app.post('/api/circuit/reset', (req: Request, res: Response) => {
  circuitBreaker.state = 'closed';
  circuitBreaker.failures = 0;
  res.json({ status: 'Circuit reset' });
});

app.get('/api/circuit/status', (_req: Request, res: Response) => {
  res.json(circuitBreaker);
});

app.get('/api/csrf-token', (req: Request, res: Response) => {
  const token = generateCsrfToken(req.sessionID);
  res.json({ token });
});

app.listen(3000, () => console.log('ML Inference Server on :3000'));

export default app;
